# Load the necessary assembly
Add-Type -AssemblyName 'System.Windows.Forms'
Add-Type -AssemblyName 'System.Drawing'

# Create the Form
$Form1 = New-Object -TypeName System.Windows.Forms.Form

# Initialize the RichTextBox
$RichTextBox1 = New-Object -TypeName System.Windows.Forms.RichTextBox

# Function to get Wi-Fi interface information
function Get-WifiInterfaceInfo {
    $output = netsh wlan show interfaces

    $wifiInfo = @{}
    $pattern = '^(?<key>[\w\s\(\)]+)\s*:\s*(?<value>.+)$'

    $output -split "`n" | ForEach-Object {
        if ($_ -match $pattern) {
            $key = $matches['key'].Trim()
            $value = $matches['value'].Trim()
            $wifiInfo[$key] = $value
        }
    }

    # Debug output to verify data
    $wifiInfo | Format-List

    [PSCustomObject]$wifiInfo
}

# Load event for Form1
$Form1_Load = {
    $wifiInfo = Get-WifiInterfaceInfo

    # Debug output to ensure data is being captured
    Write-Output "Wifi Info:"
    $wifiInfo | Format-List

    $signalStrength = $wifiInfo.Signal
    $connectionState = $wifiInfo.State
    $receiveRate = $wifiInfo.'Receive rate (Mbps)'
    $transmitRate = $wifiInfo.'Transmit rate (Mbps)'
    $wifiSSID = $wifiInfo.SSID

    $RichTextBox1.Clear()
    $RichTextBox1.AppendText("Wifi SSID: $wifiSSID `r`n")
    $RichTextBox1.AppendText("Signal Strength: $signalStrength `r`n")
    $RichTextBox1.AppendText("Connection State: $connectionState `r`n")
    $RichTextBox1.AppendText("Rx Rate: $receiveRate `r`n")
    $RichTextBox1.AppendText("Tx Rate: $transmitRate `r`n")

    $Timer = New-Object -TypeName System.Windows.Forms.Timer
    $Timer.Interval = 2000  # Update every 2 seconds
    $Timer.Add_Tick({
        $wifiInfo = Get-WifiInterfaceInfo
        $signalStrength = $wifiInfo.Signal
        $connectionState = $wifiInfo.State
        $receiveRate = $wifiInfo.'Receive rate (Mbps)'
        $transmitRate = $wifiInfo.'Transmit rate (Mbps)'
        $wifiSSID = $wifiInfo.SSID

        $RichTextBox1.Clear()
        $RichTextBox1.AppendText("Wifi SSID: $wifiSSID `r`n")
        $RichTextBox1.AppendText("Signal Strength: $signalStrength `r`n")
        $RichTextBox1.AppendText("Connection State: $connectionState `r`n")
        $RichTextBox1.AppendText("Rx Rate: $receiveRate `r`n")
        $RichTextBox1.AppendText("Tx Rate: $transmitRate `r`n")
    })

    # Start the Timer
    $Timer.Start()
}

# Function to initialize the components of the Form
function InitializeComponent {
    # Configure RichTextBox1
    $RichTextBox1.Location = [System.Drawing.Point]@{X=12; Y=12}
    $RichTextBox1.Name = 'RichTextBox1'
    $RichTextBox1.ReadOnly = $true
    $RichTextBox1.Size = [System.Drawing.Size]@{Width=260; Height=237}
    $RichTextBox1.TabIndex = 0
    $RichTextBox1.Text = ''

    $Form1.Controls.Add($RichTextBox1)
    $Form1.FormBorderStyle = [System.Windows.Forms.FormBorderStyle]::FixedDialog
    $Form1.StartPosition = [System.Windows.Forms.FormStartPosition]::CenterScreen
    $Form1.Text = 'Wifi Viewer'
    $Form1.add_Load($Form1_Load)
    $Form1.TopMost = $true
    $Form1.Icon = New-Object -TypeName System.Drawing.Icon -ArgumentList @(New-Object -TypeName  System.IO.MemoryStream -ArgumentList @(,[System.Convert]::FromBase64String('')))
}

# Call the InitializeComponent function to set up the Form
InitializeComponent

# Show the Form
$Form1.ShowDialog()